27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "title")
39	    private String title;
40	
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "address_line1")
46	    private String addressLine1;
47	
48	    @Column(name = "address_line2")
49	    private String addressLine2;
50	
51	    @Column(name = "city")
52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "telephone")
56	    @NotEmpty
57	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form: a '+' followed by 8 to 15 digits")
58	    private String telephone;
59	
60	    @Column(name = "email")
61	    private String email;
62	
63	    @Column(name = "postcode")
64	    private String postcode;
65	
66	    @Column(name = "registration_date")
67	    private LocalDate registrationDate;
68	
69	    @Column(name = "birth_date")
70	    private LocalDate birthDate;
71	
72	    @Column(name = "customer_code")
73	    private String customerCode;
74	
75	    @Column(name = "household_id")
76	    private String householdId;
77	
78	    @Column(name = "namesake_count")
79	    private Integer namesakeCount;
80	
81	    @Column(name = "household_size")
82	    private Integer householdSize;
83	
84	    @Column(name = "bulk_signup_warning")
85	    private Boolean bulkSignupWarning;
86	
87	    @Column(name = "possible_duplicate")
88	    private Boolean possibleDuplicate;
89	
90	    @Column(name = "possible_duplicate_of")
91	    private Integer possibleDuplicateOf;
92	
93	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
94	    private Set<Pet> pets;
95	
96	    public String getTitle() {
97	        return this.title;
98	    }
99	
100	    public void setTitle(String title) {
101	        this.title = title;
102	    }
103	
104	    public String getAddress() {
105	        return this.address;
106	    }
107	
108	    public void setAddress(String address) {
109	        this.address = address;
110	    }
111	
112	    public String getAddressLine1() {
113	        return this.addressLine1;
114	    }
115	
116	    public void setAddressLine1(String addressLine1) {
117	        this.addressLine1 = addressLine1;
118	    }
119	
120	    public String getAddressLine2() {
121	        return this.addressLine2;
122	    }
123	
124	    public void setAddressLine2(String addressLine2) {
125	        this.addressLine2 = addressLine2;
126	    }
127	
128	    public String getCity() {
129	        return this.city;
130	    }
131	
132	    public void setCity(String city) {
133	        this.city = city;
134	    }
135	
136	    public String getTelephone() {
137	        return this.telephone;
138	    }
139	
140	    public void setTelephone(String telephone) {
141	        this.telephone = telephone;
142	    }
143	
144	    public String getEmail() {
145	        return this.email;
146	    }
147	
148	    public void setEmail(String email) {
149	        this.email = email;
150	    }
151	
152	    public String getPostcode() {
153	        return this.postcode;
154	    }
155	
156	    public void setPostcode(String postcode) {
157	        this.postcode = postcode;
158	    }
159	
160	    public LocalDate getRegistrationDate() {
161	        return this.registrationDate;
162	    }
163	
164	    public void setRegistrationDate(LocalDate registrationDate) {
165	        this.registrationDate = registrationDate;
166	    }
167	
168	    public LocalDate getBirthDate() {
169	        return this.birthDate;
170	    }
171	
172	    public void setBirthDate(LocalDate birthDate) {
173	        this.birthDate = birthDate;
174	    }
175	
176	    public String getCustomerCode() {
177	        return this.customerCode;
178	    }
179	
180	    public void setCustomerCode(String customerCode) {
181	        this.customerCode = customerCode;
182	    }
183	
184	    public String getHouseholdId() {
185	        return this.householdId;
186	    }
187	
188	    public void setHouseholdId(String householdId) {
189	        this.householdId = householdId;
190	    }
191	
192	    public Integer getNamesakeCount() {
193	        return this.namesakeCount;
194	    }
195	
196	    public void setNamesakeCount(Integer namesakeCount) {
197	        this.namesakeCount = namesakeCount;
198	    }
199	
200	    public Integer getHouseholdSize() {
201	        return this.householdSize;
202	    }
203	
204	    public void setHouseholdSize(Integer householdSize) {
205	        this.householdSize = householdSize;
206	    }
207	
208	    public Boolean getBulkSignupWarning() {
209	        return this.bulkSignupWarning;
210	    }
211	
212	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
213	        this.bulkSignupWarning = bulkSignupWarning;
214	    }
215	
216	    public Boolean getPossibleDuplicate() {
217	        return this.possibleDuplicate;
218	    }
219	
220	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
221	        this.possibleDuplicate = possibleDuplicate;
222	    }
223	
224	    public Integer getPossibleDuplicateOf() {
225	        return this.possibleDuplicateOf;
226	    }
227	
228	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
229	        this.possibleDuplicateOf = possibleDuplicateOf;
230	    }
231	
232	    protected Set<Pet> getPetsInternal() {
233	        if (this.pets == null) {
234	            this.pets = new HashSet<>();
235	        }
236	        return this.pets;
237	    }
238	
239	    protected void setPetsInternal(Set<Pet> pets) {
240	        this.pets = pets;
241	    }
242	
243	    public List<Pet> getPets() {
244	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
245	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
246	        return Collections.unmodifiableList(sortedPets);
247	    }
248	
249	    public void setPets(List<Pet> pets) {
250	        this.pets = new HashSet<>(pets);
251	    }
252	
253	    public void addPet(Pet pet) {
254	        getPetsInternal().add(pet);
255	        pet.setOwner(this);
256	    }
257	
258	    /**
259	     * Return the Pet with the given name, or null if none found for this Owner.
260	     *
261	     * @param name to test
262	     * @return true if pet name is already in use
263	     */
264	    public Pet getPet(String name) {
265	        return getPet(name, false);
266	    }
267	
268	    /**
269	     * Return the Pet with the given name, or null if none found for this Owner.
270	     *
271	     * @param name to test
272	     * @return true if pet name is already in use
273	     */
274	    public Pet getPet(String name, boolean ignoreNew) {
275	        name = name.toLowerCase();
276	        for (Pet pet : getPetsInternal()) {
277	            if (!ignoreNew || !pet.isNew()) {
278	                String compName = pet.getName();
279	                compName = compName.toLowerCase();
280	                if (compName.equals(name)) {
281	                    return pet;
282	                }
283	            }
284	        }
285	        return null;
286	    }
287	
288	    public Pet getPet(Integer petId) {
289	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
290	    }
291	
292	    @Override
293	    public String toString() {
294	        return new ToStringCreator(this)
295	
296	            .append("id", this.getId())
297	            .append("new", this.isNew())
298	            .append("lastName", this.getLastName())
299	            .append("firstName", this.getFirstName())
300	            .append("address", this.address)
301	            .append("city", this.city)
302	            .append("telephone", this.telephone)
303	            .toString();
304	    }
305	}
