44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
109	        this.clinicService.createOwner(owner, sharesHousehold);
110	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
111	        headers.setLocation(UriComponentsBuilder.newInstance()
112	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
113	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
119	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
120	        if (currentOwner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        currentOwner.setAddressLine1(AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1()));
124	        currentOwner.setAddressLine2(AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2()));
125	        currentOwner.setAddress(AddressComposer.compose(ownerFieldsDto.getAddressLine1(),
126	            ownerFieldsDto.getAddressLine2(), ownerFieldsDto.getAddress()));
127	        currentOwner.setCity(ownerFieldsDto.getCity());
128	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
129	        currentOwner.setLastName(ownerFieldsDto.getLastName());
130	        currentOwner.setTitle(ownerFieldsDto.getTitle());
131	        currentOwner.setTelephone(TelephoneNormalizer.toE164(ownerFieldsDto.getTelephone()).orElse(null));
132	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
133	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
134	        this.clinicService.saveOwner(currentOwner);
135	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Transactional
140	    @Override
141	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
142	        Owner owner = this.clinicService.findOwnerById(ownerId);
143	        if (owner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        this.clinicService.deleteOwner(owner);
147	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
153	        Owner owner = this.clinicService.findOwnerById(ownerId);
154	        if (owner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        HttpHeaders headers = new HttpHeaders();
158	        Pet pet = petMapper.toPet(petFieldsDto);
159	        owner.setId(ownerId);
160	        pet.setOwner(owner);
161	        pet.getType().setName(null);
162	        this.clinicService.savePet(pet);
163	        PetDto petDto = petMapper.toPetDto(pet);
164	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
165	            .buildAndExpand(pet.getId()).toUri());
166	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
172	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
173	        if (currentOwner != null) {
174	            Pet currentPet = this.clinicService.findPetById(petId);
175	            if (currentPet != null) {
176	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
177	                currentPet.setName(petFieldsDto.getName());
178	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
179	                this.clinicService.savePet(currentPet);
180	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
181	            }
182	        }
183	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
189	        HttpHeaders headers = new HttpHeaders();
190	        Visit visit = visitMapper.toVisit(visitFieldsDto);
191	        Pet pet = new Pet();
192	        pet.setId(petId);
193	        visit.setPet(pet);
194	        this.clinicService.saveVisit(visit);
195	        VisitDto visitDto = visitMapper.toVisitDto(visit);
196	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
197	            .buildAndExpand(visit.getId()).toUri());
198	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
199	    }
200	
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
205	        Owner owner = this.clinicService.findOwnerById(ownerId);
206	        if (owner != null) {
207	            Pet pet = owner.getPet(petId);
208	            if (pet != null) {
209	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
210	            }
211	        }
212	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	    }
214	}
