264	    @Override
265	    @Transactional
266	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
267	        if (DisposableEmailDomains.isDisposable(owner.getEmail())) {
268	            throw new DisposableEmailDomainException(owner.getEmail());
269	        }
270	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
271	        rejectIdentityCollision(owner);
272	        List<Owner> householdMembers = findHouseholdMembers(owner);
273	        if (!householdMembers.isEmpty() && !sharesHousehold) {
274	            throw new HouseholdDuplicateException(owner.getHouseholdId());
275	        }
276	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
277	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
278	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
279	        }
280	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
281	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
282	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
283	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
284	            throw new DailyOwnerLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
285	        }
286	        owner.setBulkSignupWarning(ownersOnDate > BULK_SIGNUP_WARNING_THRESHOLD);
287	        flagPossibleDuplicate(owner, householdMembers, sharesHousehold);
288	        owner.setNamesakeCount(countNamesakes(owner));
289	        owner.setHouseholdSize(householdMembers.size() + 1);
290	        owner.setCustomerCode(assignCustomerCode(owner));
291	        ownerRepository.save(owner);
292	        ownerAuditLogger.ownerCreated(owner);
293	        return owner.getHouseholdId();
294	    }
