296	    /**
297	     * Reject creating an owner whose whole {@link OwnerIdentityKey identity key} already belongs to
298	     * another owner. Because the telephone is part of the key, only an existing owner sharing every
299	     * key component (normalized telephone, email and household identifier) is a duplicate.
300	     */
301	    private void rejectIdentityCollision(Owner owner) {
302	        String identityKey = OwnerIdentityKey.of(owner);
303	        boolean collides = ownerRepository.findByTelephone(owner.getTelephone()).stream()
304	            .anyMatch(existing -> identityKey.equals(OwnerIdentityKey.of(existing)));
305	        if (collides) {
306	            throw new DuplicateOwnerException(identityKey);
307	        }
308	    }
