312	     * base code is derived from the owner's locality, telephone and last name; if it already belongs
313	     * to another owner it is suffixed with the smallest {@code "-<n>"} (n &gt;= 2) that is still free.
314	     */
315	    private String assignCustomerCode(Owner owner) {
316	        String baseCode = CustomerCodeGenerator.format(
317	            LocalityResolver.resolve(owner.getCity(), owner.getPostcode()),
318	            owner.getTelephone(), owner.getLastName());
319	        Set<String> takenCodes = ownerRepository.findByCustomerCodeStartingWith(baseCode).stream()
320	            .map(Owner::getCustomerCode)
321	            .collect(Collectors.toSet());
322	        return CustomerCodeGenerator.deduplicate(baseCode, takenCodes::contains);
