332	     * member rather than a suspected duplicate, so it is never flagged.
333	     */
334	    private void flagPossibleDuplicate(Owner owner, List<Owner> householdMembers, boolean sharesHousehold) {
335	        Owner match = sharesHousehold ? null : householdMembers.stream()
336	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
337	            .min(Comparator.comparingInt(Owner::getId))
338	            .orElse(null);
339	        owner.setPossibleDuplicate(match != null);
340	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
341	    }
