226	    @Transactional
227	    public void savePet(Pet pet) throws DataAccessException {
228	        pet.setType(findPetTypeById(pet.getType().getId()));
229	        petRepository.save(pet);
230	    }
231	
232	    @Override
233	    @Transactional
234	    public void saveVisit(Visit visit) throws DataAccessException {
235	        visitRepository.save(visit);
236	
237	    }
238	
239	    @Override
240	    @Transactional(readOnly = true)
241	    public Collection<Vet> findVets() throws DataAccessException {
242	        return vetRepository.findAll();
243	    }
244	
245	    /**
246	     * Maximum number of owners allowed in a single city. Creating an owner in a city that has
247	     * already reached this many owners is rejected as a conflict.
248	     */
249	    static final int MAX_OWNERS_PER_CITY = 50;
250	
251	    /**
252	     * Maximum number of owners allowed to register on a single day. Creating an owner once a day has
253	     * already reached this many registrations is rejected as a rate-limit violation.
254	     */
255	    static final int MAX_OWNERS_PER_DAY = 100;
256	
257	    /**
258	     * Number of owners that must already have registered on a day before a new registration is
259	     * flagged with a bulk-signup warning. Once the count already recorded for the day exceeds this
260	     * value, the new owner carries {@code bulkSignupWarning == true}.
261	     */
262	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
263	
264	    @Override
265	    @Transactional
266	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
267	        if (DisposableEmailDomains.isDisposable(owner.getEmail())) {
268	            throw new DisposableEmailDomainException(owner.getEmail());
269	        }
270	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
271	        rejectIdentityCollision(owner);
272	        List<Owner> householdMembers = findHouseholdMembers(owner);
273	        if (!householdMembers.isEmpty() && !sharesHousehold) {
274	            throw new HouseholdDuplicateException(owner.getHouseholdId());
275	        }
276	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
277	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
278	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
279	        }
280	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
281	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
282	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
283	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
284	            throw new DailyOwnerLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
285	        }
286	        owner.setBulkSignupWarning(ownersOnDate > BULK_SIGNUP_WARNING_THRESHOLD);
287	        flagPossibleDuplicate(owner, householdMembers, sharesHousehold);
288	        owner.setNamesakeCount(countNamesakes(owner));
289	        owner.setHouseholdSize(householdMembers.size() + 1);
290	        owner.setCustomerCode(assignCustomerCode(owner));
291	        ownerRepository.save(owner);
292	        ownerAuditLogger.ownerCreated(owner);
293	        return owner.getHouseholdId();
294	    }
295	
296	    /**
297	     * Reject creating an owner whose whole {@link OwnerIdentityKey identity key} already belongs to
298	     * another owner. Because the telephone is part of the key, only an existing owner sharing every
299	     * key component (normalized telephone, email and household identifier) is a duplicate.
300	     */
301	    private void rejectIdentityCollision(Owner owner) {
302	        String identityKey = OwnerIdentityKey.of(owner);
303	        boolean collides = ownerRepository.findByTelephone(owner.getTelephone()).stream()
304	            .anyMatch(existing -> identityKey.equals(OwnerIdentityKey.of(existing)));
305	        if (collides) {
306	            throw new DuplicateOwnerException(identityKey);
307	        }
308	    }
309	
310	    /**
311	     * Build the new owner's {@code customerCode} and de-duplicate it against existing owners. The
312	     * base code is derived from the owner's locality, telephone and last name; if it already belongs
313	     * to another owner it is suffixed with the smallest {@code "-<n>"} (n &gt;= 2) that is still free.
314	     */
315	    private String assignCustomerCode(Owner owner) {
316	        String baseCode = CustomerCodeGenerator.format(
317	            LocalityResolver.resolve(owner.getCity(), owner.getPostcode()),
318	            owner.getTelephone(), owner.getLastName());
319	        Set<String> takenCodes = ownerRepository.findByCustomerCodeStartingWith(baseCode).stream()
320	            .map(Owner::getCustomerCode)
321	            .collect(Collectors.toSet());
322	        return CustomerCodeGenerator.deduplicate(baseCode, takenCodes::contains);
323	    }
324	
325	    /**
326	     * Flag the new owner as a possible (soft) duplicate of an existing household member carrying a
327	     * different telephone. The new owner is still created; {@code possibleDuplicate} is set to
328	     * whether such a match exists and {@code possibleDuplicateOf} to the matching owner's id (the
329	     * lowest when several match), or {@code null} when there is no match.
330	     *
331	     * <p>An owner that explicitly declares {@code sharesHousehold} is a <em>declared</em> household
332	     * member rather than a suspected duplicate, so it is never flagged.
333	     */
334	    private void flagPossibleDuplicate(Owner owner, List<Owner> householdMembers, boolean sharesHousehold) {
335	        Owner match = sharesHousehold ? null : householdMembers.stream()
336	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
337	            .min(Comparator.comparingInt(Owner::getId))
338	            .orElse(null);
339	        owner.setPossibleDuplicate(match != null);
340	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
341	    }
342	
343	    @Override
344	    @Transactional
345	    public void saveOwner(Owner owner) throws DataAccessException {
346	        ownerRepository.save(owner);
347	    }
348	
349	    /**
350	     * Count the owners that already exist sharing this owner's first name and last name, compared
351	     * case-insensitively. Invoked before the new owner is persisted, so it never counts itself.
352	     */
353	    private int countNamesakes(Owner owner) {
354	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
355	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName()))
356	            .count();
357	    }
358	
359	    /**
360	     * Find the existing owners that already share this owner's household, i.e. that derive the same
361	     * computed {@code householdId} (the same last name and postcode). An owner without a postcode
362	     * has no household peers.
363	     */
364	    private List<Owner> findHouseholdMembers(Owner owner) {
365	        if (owner.getPostcode() == null) {
366	            return List.of();
367	        }
368	        String householdId = owner.getHouseholdId();
369	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
370	            .filter(existing -> householdId.equals(
371	                HouseholdIdGenerator.generate(existing.getLastName(), existing.getPostcode())))
372	            .toList();
373	    }
374	
375	    @Override
376	    @Transactional(readOnly = true)
377	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
378	        return ownerRepository.findByLastName(lastName);
379	    }
380	
381	    @Override
382	    @Transactional(readOnly = true)
383	    public Collection<Visit> findVisitsByPetId(int petId) {
384	        return visitRepository.findByPetId(petId);
385	    }
386	
387	    @Override
388	    @Transactional(readOnly = true)
389	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
390	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
391	    }
392	
393	    private <T> T findEntityById(Supplier<T> supplier) {
394	        try {
395	            return supplier.get();
396	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
397	            // Just ignore not found exceptions for Jdbc/Jpa realization
398	            return null;
399	        }
400	    }
401	
402	}
403

